const projectForm=document.querySelector('[data-project-form]');const modelParam=new URLSearchParams(location.search).get('model');if(modelParam&&projectForm?.elements.model)projectForm.elements.model.value=modelParam;projectForm?.addEventListener('submit',(event)=>{event.preventDefault();const data=new FormData(event.currentTarget);const text=['SUNY Project Inquiry','',...Array.from(data.entries()).map(([key,value])=>`${key}: ${value}`)].join('\n');const url=URL.createObjectURL(new Blob(['\ufeff',text],{type:'text/plain;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=`SUNY-${(data.get('model')||'project').replace(/[^a-z0-9-]/gi,'')}-brief.txt`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
